def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = my.count('C')
    my_d = n - my_c

    last_my, last_opp = history[-1]

    # Full cooperation tracking
    if opp_d == 0:
        # Don't break perfect cooperation unless very end and only if we've
        # never been punished (opponent always cooperated).
        if n >= 99:
            return 'C'
        return 'C'

    # Perfect mutual defection / opponent has been nearly always defecting
    if opp_c == 0:
        # Opponent is pure defector; defect back with rare probes to test for change.
        if n >= 3 and n % 7 == 0:
            return 'C'
        return 'D'

    opp_rate = opp_c / n

    # Cooperative streak on both sides - preserve it
    if last_opp == 'C' and last_my == 'C':
        # Occasionally probe against very cooperative opponents (rare), but
        # keep cooperation as the dominant behavior.
        if opp_rate > 0.85 and n >= 6 and n % 17 == 0:
            return 'D'
        return 'C'

    # Opponent just cooperated while we defected: reconcile
    if last_opp == 'C' and last_my == 'D':
        # Return to cooperation to rebuild mutual cooperation.
        # Only keep exploiting if opponent has shown they never retaliate,
        # which is captured by opp_rate being very high.
        if opp_rate > 0.9 and n < 90:
            # occasionally continue exploiting a non-retaliator late
            if rng.random() < 0.4:
                return 'D'
        return 'C'

    # Opponent just defected
    if last_opp == 'D':
        # Detect consecutive opponent defections
        opp_streak_d = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                opp_streak_d += 1
            else:
                break

        # If opponent has a rare/isolated defection, forgive quickly.
        if opp_rate > 0.75 and opp_streak_d <= 1:
            return 'D'  # one retaliation for the defection
        if opp_rate > 0.85 and opp_streak_d <= 1 and n >= 2 and opp[-2] == 'C':
            # brief retaliation then back to C next round
            return 'D'

        # Long opponent defection streak: stay in defection but test forgiveness.
        if opp_streak_d >= 3:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

        # Moderate defection: tit-for-tat with forgiveness
        if opp_rate > 0.5:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    return 'C'
